const keep = (key) => typeof key === "string" && ${predicate};
export const env = new Proxy(
  {},
  {
    get: (_, key) => (keep(key) ? process.env[key] : undefined),
    has: (_, key) => keep(key) && key in process.env,
    ownKeys: () => Object.keys(process.env).filter(keep),
